class Solution {
public:
    double findMedianSortedArrays(vector<int>& nums1, vector<int>& nums2) {
        // Ensure nums1 is the smaller array
        if (nums1.size() > nums2.size())
            return findMedianSortedArrays(nums2, nums1);

        int m = nums1.size();
        int n = nums2.size();
        int low = 0, high = m;
        const int INF = numeric_limits<int>::max();
        const int NINF = numeric_limits<int>::min();

        while (low <= high) {
            int i = (low + high) / 2;               // cut in nums1
            int j = (m + n + 1) / 2 - i;            // cut in nums2

            int left1  = (i == 0) ? NINF : nums1[i - 1];
            int right1 = (i == m) ? INF  : nums1[i];
            int left2  = (j == 0) ? NINF : nums2[j - 1];
            int right2 = (j == n) ? INF  : nums2[j];

            if (left1 <= right2 && left2 <= right1) {
                // Correct partition found
                if ((m + n) % 2 == 1) {
                    return static_cast<double>(max(left1, left2));
                } else {
                    double lo = static_cast<double>(max(left1, left2));
                    double hi = static_cast<double>(min(right1, right2));
                    return (lo + hi) / 2.0;
                }
            } else if (left1 > right2) {
                // i is too big, move left
                high = i - 1;
            } else {
                // i is too small, move right
                low = i + 1;
            }
        }
        // Should never reach here if input sizes are valid
        return 0.0;
    }
};
